import{c as t,Q as s,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Session Insights — /qp v2.0.0 + Fable 5 Harness + 知識空缺研究","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-16-session-insights-qp-v2-fable5-harness.md","filePath":"research/reports/2026-06-16-session-insights-qp-v2-fable5-harness.md","lastUpdated":1785909234000}'),r={name:"research/reports/2026-06-16-session-insights-qp-v2-fable5-harness.md"};function n(i,e,l,d,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="session-insights-—-qp-v2-0-0-fable-5-harness-知識空缺研究" tabindex="-1">Session Insights — /qp v2.0.0 + Fable 5 Harness + 知識空缺研究 <a class="header-anchor" href="#session-insights-—-qp-v2-0-0-fable-5-harness-知識空缺研究" aria-label="Permalink to &quot;Session Insights — /qp v2.0.0 + Fable 5 Harness + 知識空缺研究&quot;">​</a></h1><blockquote><p><strong>日期</strong>: 2026-06-16<br><strong>來源</strong>: Session B（feat/qp-v2-fable5-harness → claude/research-article-scoring-dkv0rn）<br><strong>類型</strong>: Session Learning Report<br><strong>Topic</strong>: Quality Pipeline v2 · Fable 5 Harness · Silent Fallback Contradiction Fix · Gap Research</p></blockquote><hr><h2 id="_1-核心任務與結果" tabindex="-1">1. 核心任務與結果 <a class="header-anchor" href="#_1-核心任務與結果" aria-label="Permalink to &quot;1. 核心任務與結果&quot;">​</a></h2><h3 id="_1-1-qp-quality-pipeline-skill-完整改寫-v1-→-v2-0-0" tabindex="-1">1.1 /qp quality-pipeline SKILL 完整改寫（v1 → v2.0.0） <a class="header-anchor" href="#_1-1-qp-quality-pipeline-skill-完整改寫-v1-→-v2-0-0" aria-label="Permalink to &quot;1.1 /qp quality-pipeline SKILL 完整改寫（v1 → v2.0.0）&quot;">​</a></h3><p><strong>驅動</strong>: fable-pilot 四問框架稽核發現 v1 有 4 Critical + 3 Medium 問題：</p><table tabindex="0"><thead><tr><th>問題</th><th>嚴重度</th><th>修正</th></tr></thead><tbody><tr><td>G3 prompt 要求輸出推理過程 → <code>reasoning_extraction</code> refusal</td><td>Critical</td><td>改為結構化輸出，只要結論</td></tr><tr><td>G1 <code>tail -1 | grep -o</code> trailing newline 靜默 pass</td><td>Critical</td><td>改為 <code>grep -o | tail -1</code></td></tr><tr><td>G3 SKIP 後無 opus fallback 描述</td><td>High</td><td>明確「手動 spawn opus」流程</td></tr><tr><td>成本數字 $10/$50 hardcoded（不準確）</td><td>Medium</td><td>改為「依官方定價頁確認」</td></tr><tr><td>G1/G2 verdict parsing 跨區不一致</td><td>Medium</td><td>統一 <code>grep -o &quot;PASS|FAIL&quot; &lt;&lt;&lt; &quot;$report&quot; | tail -1</code></td></tr><tr><td>G2 不短路說明缺失</td><td>Medium</td><td>加入 Phase 2-G2 header 說明</td></tr></tbody></table><p><strong>v2 新架構特色</strong>：</p><ul><li><strong>G1 in-parent bash 優先</strong>：不 spawn agent，速度快、無 context 開銷、確定性強</li><li><strong>fail_count 機制</strong>：3 個 gate 全跑完後統計，G2 FAIL 仍可提供修正建議</li><li><strong>G3 SKIP 手動路徑</strong>：parent 偵測 <code>G3_VERDICT: SKIP</code> → 手動 spawn opus 重執行</li><li><strong>Fable 5 相容表</strong>：6 個官方 gotcha（reasoning_extraction / stop_reason refusal 等）</li><li><strong>Fresh-context verifier</strong>: 每個 gate 是獨立 sub-agent，符合 Fable 5 官方建議</li></ul><h3 id="_1-2-workspace-矛盾修正-「silent-fallback」→「顯式路由」" tabindex="-1">1.2 Workspace 矛盾修正：「silent fallback」→「顯式路由」 <a class="header-anchor" href="#_1-2-workspace-矛盾修正-「silent-fallback」→「顯式路由」" aria-label="Permalink to &quot;1.2 Workspace 矛盾修正：「silent fallback」→「顯式路由」&quot;">​</a></h3><p><strong>矛盾來源</strong>：4 個不同檔案對 Fable 5 安全分類器行為的描述不一致：</p><table tabindex="0"><thead><tr><th>檔案</th><th>舊措辭（錯誤）</th><th>新措辭（修正）</th></tr></thead><tbody><tr><td><code>fable-pilot/SKILL.md</code> frontmatter</td><td><code>Fable silent fallback → 直接指定 Opus 4.8</code></td><td><code>Fable 顯式通知路由 Opus 4.8 → 直接指定 Opus 避免賭路由</code></td></tr><tr><td><code>fable-pilot/SKILL.md</code> Preconditions</td><td><code>Silent fallback：…自動降轉 Opus 4.8</code></td><td><code>顯式路由（非靜默）：…顯示模型切換通知後路由至 Opus 4.8</code></td></tr><tr><td><code>fable-pilot/GOTCHAS.md</code></td><td><code>觸發時無顯式告警</code></td><td><code>觸發時顯示模型切換通知（用戶可見，非靜默降轉）</code>（更正記錄）</td></tr><tr><td><code>opus-pilot/SKILL.md</code> §Fable 5 Escalation</td><td><code>cyber/bio prompts may silent-fallback on Fable 5</code></td><td><code>trigger Fable 5&#39;s safety classifier → explicit model-switch notification shown</code></td></tr></tbody></table><p><strong>根因</strong>：fable-pilot SKILL 初版（2026-06-11）基於訓練知識假設「靜默降轉」；官方 Fable 5 文件確認為顯式通知；GOTCHAS.md 記錄了舊假設但未更新。</p><p><strong>修正原則</strong>：「不依賴路由行為」的操作建議保持不變；只有「是否靜默」的描述更正。</p><hr><h2 id="_2-知識空缺研究結果-gap-1–4" tabindex="-1">2. 知識空缺研究結果（GAP 1–4） <a class="header-anchor" href="#_2-知識空缺研究結果-gap-1–4" aria-label="Permalink to &quot;2. 知識空缺研究結果（GAP 1–4）&quot;">​</a></h2><p>完整研究檔案位於 <code>/tmp/claude-scratch/gap{1-4}*.md</code>（session 結束後消失，已摘要如下）。</p><h3 id="gap-1-—-fable-mythos-coverage" tabindex="-1">GAP 1 — Fable-Mythos Coverage <a class="header-anchor" href="#gap-1-—-fable-mythos-coverage" aria-label="Permalink to &quot;GAP 1 — Fable-Mythos Coverage&quot;">​</a></h3><ul><li><strong>狀態</strong>: workspace 已有完整知識；INDEX.md 前 session 已補齊兩篇 scored 文章</li><li><strong>發現</strong>：雙模型架構（Fable 5 = 公眾 + 安全分類器；Mythos 5 = 受邀 + 寬鬆分類器）</li><li><strong>發現</strong>：出口管制事件序列（jailbreak → 90 分鐘通知 → 全球暫停）— AI 模型首次納入 EAR</li><li><strong>待確認</strong>：恢復時間表、jailbreak 具體內容（未公開）</li></ul><h3 id="gap-2-—-nested-subagents-architecture-depth-5" tabindex="-1">GAP 2 — Nested Subagents Architecture（depth 5） <a class="header-anchor" href="#gap-2-—-nested-subagents-architecture-depth-5" aria-label="Permalink to &quot;GAP 2 — Nested Subagents Architecture（depth 5）&quot;">​</a></h3><ul><li><strong>狀態</strong>: workspace 有基礎 subagent 知識，depth-5 specifics 完全空白</li><li><strong>現有知識整理</strong>：fan-out ≤4（主對話）、CLAUDE.md 引入深度 5（非 subagent spawn 深度）、Fable 更積極委派</li><li><strong>對 harness 影響</strong>：unverified_success gate 需升級為每層驗證；nested overhead 1.63–1.84×</li><li><strong>待確認</strong>：depth-5 API 實現、無限遞迴防護機制、與 dynamic workflow 的交互</li></ul><h3 id="gap-3-—-claude-code-session-cost-analysis" tabindex="-1">GAP 3 — Claude Code Session Cost Analysis <a class="header-anchor" href="#gap-3-—-claude-code-session-cost-analysis" aria-label="Permalink to &quot;GAP 3 — Claude Code Session Cost Analysis&quot;">​</a></h3><ul><li><strong>狀態</strong>: workspace 有定價 + AgentsView + token budget 零散知識，$12 session 分析空缺</li><li><strong>現有知識整理</strong>：<code>/usage</code> 細分（skill/subagent/plugin）、<code>--max-budget-usd</code>（research preview）、<code>claude agents --json</code></li><li><strong>對 harness 影響</strong>：overnight 任務需強制 <code>--max-budget-usd</code>；Fable 5 積極委派行為是成本乘數</li><li><strong>待確認</strong>：Simon Willison $12 session 具體 token 細分、Usage Guard 工具性質</li></ul><h3 id="gap-4-—-safety-classifier-design" tabindex="-1">GAP 4 — Safety Classifier Design <a class="header-anchor" href="#gap-4-—-safety-classifier-design" aria-label="Permalink to &quot;GAP 4 — Safety Classifier Design&quot;">​</a></h3><ul><li><strong>狀態</strong>: workspace 有技術設計細節，靜默降級倫理事件空缺</li><li><strong>重要澄清</strong>：Fable 5 安全分類器觸發時為<strong>顯式通知</strong>（本 session 直接修正了 workspace 4 個檔案的錯誤描述）</li><li><strong>技術規格</strong>：三域（cybersecurity / biology &amp; chemistry / distillation）；&lt; 5% session 觸發；1000+ 小時紅隊無通用 jailbreak</li><li><strong>待確認</strong>：Anthropic 靜默降級政策走回事件的完整細節（外部來源）</li></ul><hr><h2 id="_3-lesson-入庫" tabindex="-1">3. Lesson 入庫 <a class="header-anchor" href="#_3-lesson-入庫" aria-label="Permalink to &quot;3. Lesson 入庫&quot;">​</a></h2><h3 id="lesson-2026-06-16-a-tail-1-grep-o-vs-grep-o-tail-1" tabindex="-1">Lesson 2026-06-16-A：<code>tail -1 | grep -o</code> vs <code>grep -o | tail -1</code> <a class="header-anchor" href="#lesson-2026-06-16-a-tail-1-grep-o-vs-grep-o-tail-1" aria-label="Permalink to &quot;Lesson 2026-06-16-A：`tail -1 | grep -o` vs `grep -o | tail -1`&quot;">​</a></h3><p><strong>失敗模式</strong>：<code>echo &quot;$report&quot; | tail -1 | grep -o &quot;PASS\\|FAIL&quot;</code> — 當 <code>$report</code> 最後一行是空行時，<code>tail -1</code> 返回空字串，<code>grep -o</code> 返回空，FAIL 被靜默吃掉。</p><p><strong>正確寫法</strong>：<code>grep -o &quot;PASS\\|FAIL&quot; &lt;&lt;&lt; &quot;$report&quot; | tail -1</code> — 搜尋所有行的 PASS/FAIL，取最後一個。</p><p><strong>適用範圍</strong>：所有「從多行輸出解析最終 verdict」的模式。</p><h3 id="lesson-2026-06-16-b-fable-5-安全分類器是顯式通知" tabindex="-1">Lesson 2026-06-16-B：Fable 5 安全分類器是顯式通知 <a class="header-anchor" href="#lesson-2026-06-16-b-fable-5-安全分類器是顯式通知" aria-label="Permalink to &quot;Lesson 2026-06-16-B：Fable 5 安全分類器是顯式通知&quot;">​</a></h3><p><strong>失敗模式</strong>：訓練知識假設分類器觸發時靜默降轉 → 寫入 SKILL/GOTCHAS.md → 傳播錯誤假設到 3+ 個檔案。</p><p><strong>防範</strong>：SKILL 初版引用模型行為時須標注「待官方文件確認」；新模型 SKILL 建立後首週標記 <code>verify-by: &lt;date&gt;</code>。</p><h3 id="lesson-2026-06-16-c-reasoning-extraction-refusal-防護" tabindex="-1">Lesson 2026-06-16-C：reasoning_extraction refusal 防護 <a class="header-anchor" href="#lesson-2026-06-16-c-reasoning-extraction-refusal-防護" aria-label="Permalink to &quot;Lesson 2026-06-16-C：reasoning_extraction refusal 防護&quot;">​</a></h3><p><strong>失敗模式</strong>：G3 prompt 要求 fable「輸出四問框架稽核」（=要求輸出推理步驟）→ 觸發 <code>reasoning_extraction</code> refusal，pipeline 卡死。</p><p><strong>防範</strong>：給 Fable 結構化輸出格式（只要結論），讓它自己決定如何推理。任何「解釋你的思考」「列出你的推導步驟」類指令都應改寫為「輸出結論」格式。</p><hr><h2 id="_4-演化候選-待人工審核" tabindex="-1">4. 演化候選（待人工審核） <a class="header-anchor" href="#_4-演化候選-待人工審核" aria-label="Permalink to &quot;4. 演化候選（待人工審核）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>候選</th><th>目標檔案</th><th>狀態</th><th>備注</th></tr></thead><tbody><tr><td>model-selection-grid-fable5</td><td><code>.claude/refs/model-selection-grid.md</code></td><td>⚠️ 待人工審核</td><td>新增 Fable 5 row（suspended + fallback 策略）；驗證：<code>grep -q &#39;claude-fable-5&#39; .claude/refs/model-selection-grid.md</code></td></tr></tbody></table><hr><h2 id="_5-本-session-的-qp-實戰結果" tabindex="-1">5. 本 Session 的 /qp 實戰結果 <a class="header-anchor" href="#_5-本-session-的-qp-實戰結果" aria-label="Permalink to &quot;5. 本 Session 的 /qp 實戰結果&quot;">​</a></h2><p>本 session 用 fable-pilot 四問框架稽核 /qp v1，再用 /qp 管道的 G1+G2 cross-review 驗 v2：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[/qp PARTIAL FAIL] G2 找到 5 issues（1 Critical + 4 Medium）</span></span>\n<span class="line"><span>→ 修正全 5 個 findings</span></span>\n<span class="line"><span>→ G1 re-verification: 5/5 checks PASS</span></span>\n<span class="line"><span>→ [/qp VERIFIED] v2.0.0 通過</span></span></code></pre></div><p>這是 /qp 的第一次<strong>自我稽核應用</strong>（pipeline 稽核 pipeline 的設計文件），驗證了 cross-review 架構能發現 self-review 看不到的問題。</p>',45)])])}const b=t(r,[["render",n]]);export{h as __pageData,b as default};
